class Solution:
    def lengthOfLongestSubstring(self, s):
        if not s:
            return 0

        char_index = {}
        left = 0
        max_length = 0

        for right in range(len(s)):
            current_char = s[right]

            # Check if character is in current window
            if current_char in char_index:
                # Move left pointer only if the duplicate is within current window
                if char_index[current_char] >= left:
                    left = char_index[current_char] + 1

            # Update character index
            char_index[current_char] = right

            # Update maximum length
            max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)

        # Early termination: if pattern is empty but string isn't
        if n == 0:
            return m == 0

        # Early termination: if string is empty, pattern must have * to match
        if m == 0:
            # Pattern can only match empty string if all chars at odd positions are *
            for j in range(1, n, 2):
                if p[j] != '*':
                    return False
            return n % 2 == 0

        # Use only two rows for space optimization
        prev = [False] * (n + 1)
        curr = [False] * (n + 1)

        # Empty string matches empty pattern
        prev[0] = True

        # Handle patterns that can match empty string (like a*, a*b*, etc.)
        for j in range(2, n + 1, 2):
            if p[j-1] == '*':
                prev[j] = prev[j-2]

        # Fill the dp table using only two rows
        for i in range(1, m + 1):
            curr[0] = False  # Non-empty string can't match empty pattern

            for j in range(1, n + 1):
                if p[j-1] == '*':
                    # Two cases: zero occurrence or one/more occurrence
                    curr[j] = curr[j-2] or (
                        (s[i-1] == p[j-2] or p[j-2] == '.') and prev[j]
                    )
                else:
                    # Normal character or '.'
                    curr[j] = (s[i-1] == p[j-1] or p[j-1] == '.') and prev[j-1]

            # Swap arrays
            prev, curr = curr, prev

        return prev[n]

class Solution:
    def maxArea(self, height):
        left = 0
        right = len(height) - 1
        max_area = 0

        while left < right:
            # Calculate current area
            current_area = min(height[left], height[right]) * (right - left)
            max_area = max(max_area, current_area)

            # Move the pointer with smaller height
            if height[left] < height[right]:
                left += 1
            else:
                right -= 1

        return max_area

class Solution:
    def generateParenthesis(self, n):
        result = []

        def backtrack(current, open_count, close_count):
            # Base case: we've used all n pairs
            if len(current) == 2 * n:
                result.append(current)
                return

            # Add opening parenthesis if we haven't used all n
            if open_count < n:
                backtrack(current + "(", open_count + 1, close_count)

            # Add closing parenthesis if it won't make the string invalid
            if close_count < open_count:
                backtrack(current + ")", open_count, close_count + 1)

        backtrack("", 0, 0)
        return result

