class Solution:
    def canJump(self, nums):
        """
        :type nums: List[int]
        :rtype: bool
        """
        if not nums:
            return False

        n = len(nums)
        if n == 1:
            return True

        # Track the leftmost index that can reach the end
        leftmost_reachable = n - 1

        # Work backwards from second-to-last element
        for i in range(n - 2, -1, -1):
            # If current position can reach the target
            if i + nums[i] >= leftmost_reachable:
                leftmost_reachable = i

        return leftmost_reachable == 0

class Solution:
    def minPathSum(self, grid):
        if not grid or not grid[0]:
            return 0

        m, n = len(grid), len(grid[0])

        # Use only one row for space optimization
        dp = [0] * n
        dp[0] = grid[0][0]

        # Initialize first row
        for j in range(1, n):
            dp[j] = dp[j-1] + grid[0][j]

        # Process each row
        for i in range(1, m):
            # First element of current row - can only come from above
            dp[0] += grid[i][0]
            # Fill the rest of the row - can come from left or above
            for j in range(1, n):
                dp[j] = grid[i][j] + min(dp[j], dp[j-1])

        return dp[n-1]

