class Solution:
    def search(self, nums, target):
        left, right = 0, len(nums) - 1

        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                return True

            # Handle duplicates by shrinking the search space
            if nums[left] == nums[mid] == nums[right]:
                left += 1
                right -= 1
            elif nums[left] <= nums[mid]:
                # Left half is sorted
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right half is sorted
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return False

class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        # Memoization dictionary
        memo = {}

        def helper(s1, s2):
            # Base case: if strings are equal, they're scrambles
            if s1 == s2:
                return True

            # Check if already computed
            if (s1, s2) in memo:
                return memo[(s1, s2)]

            # If lengths don't match or character frequencies don't match
            if len(s1) != len(s2) or sorted(s1) != sorted(s2):
                memo[(s1, s2)] = False
                return False

            n = len(s1)

            # Try all possible split points
            for i in range(1, n):
                # Case 1: No swap - s1[0:i] matches s2[0:i] and s1[i:] matches s2[i:]
                if (helper(s1[:i], s2[:i]) and helper(s1[i:], s2[i:])):
                    memo[(s1, s2)] = True
                    return True

                # Case 2: Swap - s1[0:i] matches s2[n-i:] and s1[i:] matches s2[0:n-i]
                if (helper(s1[:i], s2[n-i:]) and helper(s1[i:], s2[:n-i])):
                    memo[(s1, s2)] = True
                    return True

            memo[(s1, s2)] = False
            return False

        return helper(s1, s2)

