class Solution:
    def restoreIpAddresses(self, s):
        def isValid(segment):
            # Empty segment
            if not segment:
                return False
            # Leading zero (except for "0" itself)
            if len(segment) > 1 and segment[0] == '0':
                return False
            # Value out of range
            if int(segment) > 255:
                return False
            return True

        def backtrack(start, path, result):
            # If we have 4 segments and consumed all characters
            if len(path) == 4:
                if start == len(s):
                    result.append('.'.join(path))
                return

            # Early termination: check if remaining characters can form valid segments
            remaining_chars = len(s) - start
            remaining_segments = 4 - len(path)

            # Minimum and maximum characters needed for remaining segments
            min_needed = remaining_segments
            max_needed = remaining_segments * 3

            if remaining_chars < min_needed or remaining_chars > max_needed:
                return

            # Try segments of length 1, 2, 3
            for length in range(1, 4):
                # Check if we have enough characters left
                if start + length > len(s):
                    break

                segment = s[start:start + length]

                # Check if current segment is valid
                if isValid(segment):
                    path.append(segment)
                    backtrack(start + length, path, result)
                    path.pop()  # Backtrack

        result = []
        backtrack(0, [], result)
        return result

