class Solution:
    def pathSum(self, root, targetSum):
        result = []

        def dfs(node, current_path, current_sum):
            if not node:
                return

            # Add current node to path and update sum
            current_path.append(node.val)
            current_sum += node.val

            # Check if it's a leaf node
            if not node.left and not node.right:
                # If sum matches target, add path to result
                if current_sum == targetSum:
                    result.append(current_path[:])  # Create a copy efficiently
            else:
                # Continue DFS on children
                dfs(node.left, current_path, current_sum)
                dfs(node.right, current_path, current_sum)

            # Backtrack: remove current node from path
            current_path.pop()

        dfs(root, [], 0)
        return result

class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m, n = len(s), len(t)

        # Handle edge cases
        if n == 0:
            return 1
        if m == 0 or n > m:
            return 0

        # Use only one row for space optimization
        dp = [0] * (n + 1)
        dp[0] = 1  # Empty string can be formed in 1 way

        # Fill the dp table
        for i in range(1, m + 1):
            # Traverse backwards to avoid using updated values in same iteration
            for j in range(min(i, n), 0, -1):
                if s[i-1] == t[j-1]:
                    dp[j] += dp[j-1]

        return dp[n]

