class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
        # Convert wordList to set for O(1) lookup
        wordSet = set(wordList)

        # If endWord is not in wordSet, return empty list
        if endWord not in wordSet:
            return []

        # Build adjacency list for words that differ by one character
        def getNeighbors(word):
            neighbors = []
            for i in range(len(word)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    if c != word[i]:
                        newWord = word[:i] + c + word[i+1:]
                        if newWord in wordSet:
                            neighbors.append(newWord)
            return neighbors

        # BFS to find shortest distances and build graph
        queue = deque([beginWord])
        visited = {beginWord: 1}
        parent_map = defaultdict(list)  # parent -> list of children

        while queue:
            current_level_size = len(queue)
            current_level_visited = set()

            for _ in range(current_level_size):
                word = queue.popleft()

                if word == endWord:
                    break

                for neighbor in getNeighbors(word):
                    if neighbor not in visited:
                        current_level_visited.add(neighbor)
                        visited[neighbor] = visited[word] + 1
                        parent_map[word].append(neighbor)
                        queue.append(neighbor)
                    elif visited[neighbor] == visited[word] + 1:
                        # This is a different path to the same level
                        parent_map[word].append(neighbor)

            # Add all words at current level to visited set
            for word in current_level_visited:
                visited[word] = visited[word]  # Just to ensure it's marked

        # If we never reached endWord, return empty list
        if endWord not in visited:
            return []

        # DFS to build all paths using parent_map
        result = []

        def dfs(current_word, path):
            if current_word == endWord:
                result.append(path[:])
                return

            for neighbor in parent_map[current_word]:
                path.append(neighbor)
                dfs(neighbor, path)
                path.pop()  # backtrack

        dfs(beginWord, [beginWord])
        return result

class Solution:
    def partition(self, s):
        n = len(s)
        # Precompute palindromes using dynamic programming
        # is_palindrome[i][j] represents whether s[i:j+1] is palindrome
        is_palindrome = [[False] * n for _ in range(n)]

        # Every single character is a palindrome
        for i in range(n):
            is_palindrome[i][i] = True

        # Check for palindromes of length 2
        for i in range(n - 1):
            if s[i] == s[i + 1]:
                is_palindrome[i][i + 1] = True

        # Check for palindromes of length 3 and more
        for length in range(3, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j] and is_palindrome[i + 1][j - 1]:
                    is_palindrome[i][j] = True

        def backtrack(start, current_partition):
            # Base case: if we've processed the entire string
            if start == n:
                result.append(current_partition[:])  # Make a copy
                return

            # Try all possible substrings starting from 'start'
            for end in range(start, n):
                # Check if current substring s[start:end+1] is palindrome
                if is_palindrome[start][end]:
                    current_partition.append(s[start:end + 1])
                    backtrack(end + 1, current_partition)
                    current_partition.pop()  # Backtrack

        result = []
        backtrack(0, [])
        return result

class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        if n <= 1:
            return 0

        # Precompute palindromes using expand around centers approach
        # This is more memory efficient than 2D array for large strings
        is_palindrome = [[False] * n for _ in range(n)]

        # Every single character is a palindrome
        for i in range(n):
            is_palindrome[i][i] = True

        # Check for palindromes of length 2
        for i in range(n - 1):
            if s[i] == s[i + 1]:
                is_palindrome[i][i + 1] = True

        # Check for palindromes of length 3 and more
        for length in range(3, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j] and is_palindrome[i + 1][j - 1]:
                    is_palindrome[i][j] = True

        # dp[i] represents minimum cuts needed for s[0:i]
        dp = [float('inf')] * (n + 1)
        dp[0] = 0  # No cuts needed for empty string

        for i in range(1, n + 1):
            for j in range(i):
                # If s[j:i] is palindrome, we can make one cut at position j
                if is_palindrome[j][i - 1]:
                    dp[i] = min(dp[i], dp[j] + 1)

        # dp[n] gives us the minimum cuts for the entire string
        # But we want cuts, not partitions, so subtract 1
        return dp[n] - 1

class Solution:
    def candy(self, ratings):
        n = len(ratings)
        if n == 0:
            return 0

        # Initialize each child with 1 candy
        candies = [1] * n

        # Left to right pass
        for i in range(1, n):
            if ratings[i] > ratings[i-1]:
                candies[i] = candies[i-1] + 1

        # Right to left pass
        for i in range(n-2, -1, -1):
            if ratings[i] > ratings[i+1] and candies[i] <= candies[i+1]:
                candies[i] = candies[i+1] + 1

        return sum(candies)

