        result = []
        stack = [root]

        while stack:
            node = stack.pop()
            result.append(node.val)

            # Push right first, then left (so left is processed first)
            # Only add non-null children to stack
            if node.right:
                stack.append(node.right)
            if node.left:
                stack.append(node.left)

        return result

class Solution:
    def findMin(self, nums):
        left, right = 0, len(nums) - 1

        while left < right:
            mid = (left + right) // 2

            # If mid element is greater than rightmost element,
            # the minimum must be in the right half
            if nums[mid] > nums[right]:
                left = mid + 1
            else:
                # If mid element is less than or equal to rightmost element,
                # the minimum is either mid or in the left half
                right = mid

        return nums[left]

class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        if not s:
            return 0

        left = 0
        max_length = 0
        char_count = {}
        n = len(s)

        for right in range(n):
            # Add current character to the window
            char_count[s[right]] = char_count.get(s[right], 0) + 1

            # If we have more than 2 distinct characters, shrink window from left
            while len(char_count) > 2:
                left_char = s[left]
                char_count[left_char] -= 1
                if char_count[left_char] == 0:
                    del char_count[left_char]
                left += 1

            # Update maximum length
            max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def majorityElement(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        candidate = None
        count = 0

        for num in nums:
            if count == 0:
                candidate = num
            if num == candidate:
                count += 1
            else:
                count -= 1

        return candidate

