class Solution:
    def largestNumber(self, nums):
        # Convert all numbers to strings
        str_nums = [str(num) for num in nums]

        # Custom comparator function
        def compare(x, y):
            # Compare x+y with y+x
            if x + y > y + x:
                return -1  # x should come before y
            elif x + y < y + x:
                return 1   # y should come before x
            else:
                return 0   # equal

        # Sort using custom comparator
        str_nums.sort(key=cmp_to_key(compare))

        # Join all numbers
        result = ''.join(str_nums)

        # Handle edge case where result is all zeros
        return '0' if result[0] == '0' else result

class Solution:
    def maxProfit(self, k, prices):
        if not prices or k == 0:
            return 0

        n = len(prices)
        if n < 2:
            return 0

        # If k is large enough to allow unlimited transactions
        if k >= n // 2:
            # This is a special case - we can do as many transactions as we want
            profit = 0
            for i in range(1, n):
                if prices[i] > prices[i-1]:
                    profit += prices[i] - prices[i-1]
            return profit

        # Initialize buy and sell arrays
        buy = [-float('inf')] * (k + 1)
        sell = [0] * (k + 1)

        for price in prices:
            # Process from right to left to avoid using updated values in same iteration
            for i in range(k, 0, -1):
                sell[i] = max(sell[i], buy[i] + price)
                buy[i] = max(buy[i], sell[i-1] - price)

        return sell[k]

class Solution:
    def rob(self, nums):
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]
        if len(nums) == 2:
            return max(nums[0], nums[1])

        # dp[i] represents max money that can be robbed up to house i
        # We only need to keep track of last two values
        prev2 = nums[0]  # dp[i-2]
        prev1 = max(nums[0], nums[1])  # dp[i-1]

        for i in range(2, len(nums)):
            current = max(prev1, prev2 + nums[i])
            prev2 = prev1
            prev1 = current

        return prev1

