class Solution:
    def rightSideView(self, root):
        if not root:
            return []

        result = []
        queue = [root]

        while queue:
            level_size = len(queue)

            # Process all nodes at current level
            for i in range(level_size):
                node = queue.pop(0)

                # Add children for next level
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            # Rightmost node is the last one processed at this level
            result.append(node.val)

        return result

class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        shift = 0
        # Keep shifting until left and right become equal
        while left != right:
            left >>= 1
            right >>= 1
            shift += 1

        # Shift back to get the common prefix
        return left << shift

class Solution:
    def isHappy(self, n: int) -> bool:
        def get_sum_of_squares(num):
            total = 0
            while num > 0:
                digit = num % 10
                total += digit * digit
                num //= 10
            return total

        seen = set()

        while n != 1 and n not in seen:
            seen.add(n)
            n = get_sum_of_squares(n)

        return n == 1

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        # Build adjacency list representation of the graph
        graph = [[] for _ in range(numCourses)]
        for course, prereq in prerequisites:
            graph[prereq].append(course)

        # 0 = unvisited, 1 = visiting, 2 = visited
        state = [0] * numCourses

        # Iterative DFS using stack
        for start in range(numCourses):
            if state[start] == 0:
                # Start DFS from this node
                stack = [start]

                while stack:
                    node = stack[-1]

                    if state[node] == 0:
                        # Mark as visiting
                        state[node] = 1
                        # Add all neighbors to stack
                        for neighbor in graph[node]:
                            if state[neighbor] == 1:  # Cycle detected
                                return False
                            if state[neighbor] == 0:
                                stack.append(neighbor)
                    else:
                        # Finish visiting this node
                        stack.pop()
                        state[node] = 2

        return True

class Solution:
    def rob(self, nums):
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]
        if len(nums) == 2:
            return max(nums[0], nums[1])

        # Helper function to calculate max money for a linear array with O(1) space
        def rob_linear(houses):
            # Only need to track last two values
            prev2 = houses[0]
            prev1 = max(houses[0], houses[1])

            for i in range(2, len(houses)):
                current = max(prev1, prev2 + houses[i])
                prev2 = prev1
                prev1 = current

            return prev1

        # Two scenarios: exclude first house OR exclude last house
        # Scenario 1: Rob houses 0 to n-2
        scenario1 = rob_linear(nums[:-1])
        # Scenario 2: Rob houses 1 to n-1  
        scenario2 = rob_linear(nums[1:])

        return max(scenario1, scenario2)

class Solution:
    def containsNearbyDuplicate(self, nums, k):
        # Dictionary to store the most recent index of each number
        num_to_index = {}

        for i, num in enumerate(nums):
            # If we've seen this number before and distance is within k
            if num in num_to_index and i - num_to_index[num] <= k:
                return True

            # Update the most recent index for this number
            num_to_index[num] = i

        return False

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        # If lengths are different, they can't be anagrams
        if len(s) != len(t):
            return False

        # Count frequency of each character
        char_count = {}

        # Count characters in first string
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1

        # Subtract character counts based on second string
        for char in t:
            if char not in char_count:
                return False
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]

        # If all characters are accounted for, the dictionary should be empty
        return len(char_count) == 0

